class _MoviePlayerState extends ConsumerState<MoviePlayerScreen>{VideoPlayerController?video;ChewieController?chewie;MovieModel?movie;String?error;Timer?timer;bool loading=true;@override void initState(){super.initState();init();}Future<void>init()async{setState(()=>loading=true);try{movie=await ref.read(contentRepositoryProvider).movie(widget.id);if(!movie!.hasFullVideo||movie!.videoUrl==null)throw const AppException('Ushbu film uchun qonuniy to‘liq video mavjud emas.');video=VideoPlayerController.networkUrl(Uri.parse(movie!.videoUrl!),videoPlayerOptions:VideoPlayerOptions(mixWithOthers:false));await video!.initialize();final history=await ref.read(contentRepositoryProvider).history();final saved=history.where((x)=>x.id==movie!.id).firstOrNull;if(saved!=null&&saved.positionSeconds>5&&saved.positionSeconds<video!.value.duration.inSeconds-10)await video!.seekTo(Duration(seconds:saved.positionSeconds));final subtitles=movie!.subtitleUrl==null?null:await _loadVtt(movie!.subtitleUrl!);chewie=ChewieController(videoPlayerController:video!,autoPlay:ref.read(authProvider).user?.autoplay??true,allowFullScreen:true,allowMuting:true,allowPlaybackSpeedChanging:true,showControlsOnInitialize:true,subtitle:subtitles,showSubtitles:subtitles!=null,subtitleBuilder:(context,text)=>Container(padding:const EdgeInsets.all(8),color:Colors.black54,child:Text(text,style:const TextStyle(color:Colors.white,fontSize:16))),placeholder:const ColoredBox(color:Colors.black),errorBuilder:(_,__)=>_PlayerError(message:'Video hozirda mavjud emas.',retry:init),additionalOptions:(_)=>[OptionItem(onTap:(context)=>Navigator.pop(context),iconData:Icons.high_quality,title:'Sifat: Avtomatik'),OptionItem(onTap:(context)=>Navigator.pop(context),iconData:subtitles==null?Icons.subtitles_off:Icons.subtitles,title:subtitles==null?'Subtitr mavjud emas':'Subtitr yoqilgan')]);await ref.read(apiClientProvider).dio.post('/movies/${movie!.id}/view',data:{'sessionId':DateTime.now().millisecondsSinceEpoch.toString()});timer=Timer.periodic(const Duration(seconds:15),(_)=>save());if(mounted)setState(()=>loading=false);}catch(e){if(mounted)setState((){error=friendlyError(e);loading=false;});}}void save(){if(movie!=null&&video?.value.isInitialized==true)ref.read(contentRepositoryProvider).saveHistory(movie!.id,video!.value.position.inSeconds,video!.value.duration.inSeconds);}@override Widget build(BuildContext context)=>PopScope(onPopInvokedWithResult:(_,__)=>save(),child:Scaffold(backgroundColor:Colors.black,appBar:AppBar(title:Text(movie?.title??'Kino playeri'),backgroundColor:Colors.black),body:Center(child:loading?const CircularProgressIndicator():error!=null?_PlayerError(message:error!,retry:(){error=null;disposePlayer();init();}):chewie==null?const SizedBox():Chewie(controller:chewie!))));void disposePlayer(){timer?.cancel();chewie?.dispose();video?.dispose();chewie=null;video=null;}@override void dispose(){save();disposePlayer();super.dispose();}}
