class _LivePlayerState extends ConsumerState<LivePlayerScreen>{VideoPlayerController?video;ChewieController?chewie;ChannelModel?channel;String?error;bool loading=true;@override void initState(){super.initState();init();}Future<void>init()async{try{channel=await ref.read(contentRepositoryProvider).channel(widget.id);if(channel!.streamUrl.isEmpty)throw const AppException('Ushbu kanalning jonli efiri hozirda mavjud emas.');video=VideoPlayerController.networkUrl(Uri.parse(channel!.streamUrl),formatHint:channel!.streamType=='HLS'?VideoFormat.hls:null);await video!.initialize();chewie=ChewieController(videoPlayerController:video!,autoPlay:true,isLive:true,allowFullScreen:true,allowMuting:true,showControlsOnInitialize:true,errorBuilder:(_,__)=>_PlayerError(message:'Ushbu kanalning jonli efiri hozirda mavjud emas.',retry:retry),additionalOptions:(_)=>[OptionItem(onTap:(c)=>Navigator.pop(c),iconData:Icons.high_quality,title:'Sifat: Avtomatik')]);await ref.read(apiClientProvider).dio.post('/channels/${channel!.id}/view',data:{'sessionId':DateTime.now().millisecondsSinceEpoch.toString()});if(mounted)setState(()=>loading=false);}catch(e){if(mounted)setState((){loading=false;error=friendlyError(e);});}}Future<void>retry()async{chewie?.dispose();await video?.dispose();chewie=null;video=null;setState((){loading=true;error=null;});await init();}@override Widget build(BuildContext context)=>Scaffold(backgroundColor:Colors.black,appBar:AppBar(backgroundColor:Colors.black,title:Row(children:[Expanded(child:Text(channel?.name??'Jonli efir')),Container(padding:const EdgeInsets.symmetric(horizontal:8,vertical:4),decoration:BoxDecoration(color:Colors.red,borderRadius:BorderRadius.circular(6)),child:const Text('● LIVE',style:TextStyle(fontSize:10,fontWeight:FontWeight.bold))) ])),body:Center(child:loading?const CircularProgressIndicator():error!=null?_PlayerError(message:error!,retry:retry):Chewie(controller:chewie!)));@override void dispose(){chewie?.dispose();video?.dispose();super.dispose();}}
