Future<Subtitles?> _loadVtt(String url)async{try{final text=(await Dio().get<String>(url,options:Options(responseType:ResponseType.plain))).data??'';final lines=text.replaceAll('\r','').split('\n');final items=<Subtitle>[];for(var i=0;i<lines.length;i++){if(!lines[i].contains('-->'))continue;final parts=lines[i].split('-->');final start=_vttTime(parts[0].trim()),end=_vttTime(parts[1].trim().split(' ').first);final body=<String>[];for(i=i+1;i<lines.length&&lines[i].trim().isNotEmpty;i++){body.add(lines[i].trim());}if(body.isNotEmpty)items.add(Subtitle(index:items.length,start:start,end:end,text:body.join('\n')));}return items.isEmpty?null:Subtitles(items);}catch(_){return null;}}
Duration _vttTime(String value){final p=value.replaceAll(',','.').split(':');final seconds=double.tryParse(p.last)??0;final minutes=p.length>1?int.tryParse(p[p.length-2])??0:0;final hours=p.length>2?int.tryParse(p[p.length-3])??0:0;return Duration(milliseconds:((hours*3600+minutes*60+seconds)*1000).round());}
